begin;
create extension if not exists pgtap with schema extensions;
select plan(52);
insert into auth.users(id,email,email_confirmed_at,encrypted_password,invited_at)
select ('e9100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
 'agency-user-'||n||'@example.test',now(),'synthetic',now() from generate_series(1,7) n;
insert into public.profiles(id,display_name) select id,'QA usuarios' from auth.users where id::text like 'e9100000-%';
insert into public.agencies(id,name,slug,ars_per_usd) values
 ('e9200000-0000-4000-8000-000000000001','QA usuarios A','qa-user-invites-a',1000),
 ('e9200000-0000-4000-8000-000000000002','QA usuarios B','qa-user-invites-b',1000);
insert into public.memberships(agency_id,user_id,role) values
 ('e9200000-0000-4000-8000-000000000001','e9100000-0000-4000-8000-000000000001','agency_superadmin'),
 ('e9200000-0000-4000-8000-000000000001','e9100000-0000-4000-8000-000000000002','admin'),
 ('e9200000-0000-4000-8000-000000000001','e9100000-0000-4000-8000-000000000003','seller'),
 ('e9200000-0000-4000-8000-000000000002','e9100000-0000-4000-8000-000000000004','agency_superadmin');
insert into public.platform_admins(user_id) values ('e9100000-0000-4000-8000-000000000007');
set local role anon;
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'42501',null,'Anonymous denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'42501',null,'Platform alone cannot manage agency users');
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"role":"agency_superadmin"}}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'42501',null,'Seller metadata cannot authorize');
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'42501',null,'Foreign owner denied');
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','admin')$$,'42501',null,'Admin cannot invite admin');
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','agency_superadmin')$$,'22023',null,'Cannot request owner role');
select lives_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001',' AGENCY-USER-5@EXAMPLE.TEST ',' QA ','seller')$$,'Admin can invite seller');
select set_config('test.user_invitation',(select id::text from public.agency_user_invitations where email='agency-user-5@example.test'),true);
select is((select count(*) from public.memberships where user_id='e9100000-0000-4000-8000-000000000005'),0::bigint,'Sending grants nothing');
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'P0001',null,'Same email has one live reservation per agency');
select throws_ok($$select public.finish_agency_user_invitation(current_setting('test.user_invitation')::uuid,'e9100000-0000-4000-8000-000000000005',true)$$,'42501',null,'Clients cannot bind identities');
select throws_ok($$update public.agency_user_invitations set role='admin'$$,'42501',null,'Clients cannot alter roles');
reset role;
select throws_ok($$select public.finish_agency_user_invitation(current_setting('test.user_invitation')::uuid,'e9100000-0000-4000-8000-000000000006',true)$$,'42501',null,'Binding validates email');
select lives_ok($$select public.finish_agency_user_invitation(current_setting('test.user_invitation')::uuid,'e9100000-0000-4000-8000-000000000005',true)$$,'Trusted adapter confirms delivery');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.agency_user_invitations),0::bigint,'Foreign owner cannot read invitations');
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'42501',null,'Wrong identity denied');
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select is((select count(*) from public.agency_user_invitations),1::bigint,'Bound recipient can read own invitation');
reset role;
update public.memberships set is_active=false where user_id='e9100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'42501',null,'Revoked inviter cannot grant later');
reset role;
update public.memberships set is_active=true where user_id='e9100000-0000-4000-8000-000000000002';
update public.agencies set is_active=false where id='e9200000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'P0002',null,'Inactive agency denied');
reset role;
update public.agencies set is_active=true where id='e9200000-0000-4000-8000-000000000001';
update public.agency_user_invitations set expires_at=now()-interval '1 second';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'P0001',null,'Expired invitation denied');
reset role;
update public.agency_user_invitations set expires_at=now()+interval '1 hour';
create function pg_temp.reject_user_acceptance_audit() returns trigger language plpgsql as $$
begin
 if new.action='user_invitation.accepted' then raise exception 'Synthetic audit failure' using errcode='22000'; end if;
 return new;
end; $$;
create trigger reject_user_acceptance_audit before insert on public.audit_events for each row execute function pg_temp.reject_user_acceptance_audit();
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'22000',null,'Audit failure rejects whole transaction');
select is(private.current_agency_role('e9200000-0000-4000-8000-000000000001'),null,'Failure leaves no membership');
select is((select status from public.agency_user_invitations where id=current_setting('test.user_invitation')::uuid),'sent','Failure retains sent state');
reset role;
drop trigger reject_user_acceptance_audit on public.audit_events;
set local role authenticated;
select lives_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'Correct recipient accepts');
select is(private.current_agency_role('e9200000-0000-4000-8000-000000000001'),'seller','Stored authorized role granted');
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.user_invitation')::uuid)$$,'P0001',null,'No duplicate redemption');
reset role;
select is((select count(*) from public.audit_events where user_invitation_id=current_setting('test.user_invitation')::uuid),3::bigint,'Delivery, membership and acceptance audited');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','admin')$$,'P0001',null,'Existing member cannot be promoted');
select lives_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-6@example.test','QA','admin')$$,'Owner can invite admin');
select set_config('test.admin_invitation',(select id::text from public.agency_user_invitations where email='agency-user-6@example.test'),true);
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.cancel_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'42501',null,'Admin cannot cancel admin invitation');
reset role;
update public.memberships set role='admin' where user_id='e9100000-0000-4000-8000-000000000001';
select throws_ok($$select public.finish_agency_user_invitation(current_setting('test.admin_invitation')::uuid,'e9100000-0000-4000-8000-000000000006',true)$$,'42501',null,'Demoted inviter cannot confirm admin delivery');
update public.memberships set role='agency_superadmin' where user_id='e9100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.cancel_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'Owner cancels pending admin invitation');
reset role;
select throws_ok($$select public.finish_agency_user_invitation(current_setting('test.admin_invitation')::uuid,'e9100000-0000-4000-8000-000000000006',true)$$,'P0001',null,'Late delivery cannot revive cancellation');
set local role authenticated;
select lives_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-6@example.test','QA','admin')$$,'Cancellation permits a new reservation');
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','bad-address','QA','seller')$$,'22023',null,'Invalid email rejected');
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','valid@example.test',' ','seller')$$,'22023',null,'Blank name rejected');
select throws_ok($$select private.lock_agency_user_inviter('e9200000-0000-4000-8000-000000000001',auth.uid(),'seller')$$,'42501',null,'Private authority helper inaccessible to clients');
select set_config('test.admin_invitation',(select id::text from public.agency_user_invitations where email='agency-user-6@example.test' and status='sending'),true);
reset role;
select public.finish_agency_user_invitation(current_setting('test.admin_invitation')::uuid,'e9100000-0000-4000-8000-000000000006',true);
update public.memberships set role='admin' where user_id='e9100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'42501',null,'Demotion after delivery blocks admin acceptance');
reset role;
update public.memberships set role='agency_superadmin' where user_id='e9100000-0000-4000-8000-000000000001';
update auth.users set encrypted_password='' where id='e9100000-0000-4000-8000-000000000006';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'42501',null,'Password required');
reset role;
update auth.users set encrypted_password='synthetic',email='changed-user@example.test' where id='e9100000-0000-4000-8000-000000000006';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'42501',null,'Current email must match');
reset role;
update auth.users set email='agency-user-6@example.test',email_confirmed_at=null where id='e9100000-0000-4000-8000-000000000006';
set local role authenticated;
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'42501',null,'Email proof required');
reset role;
update auth.users set email_confirmed_at=now() where id='e9100000-0000-4000-8000-000000000006';
set local role authenticated;
select lives_ok($$select public.accept_agency_user_invitation(current_setting('test.admin_invitation')::uuid)$$,'Owner invitation grants admin after verified acceptance');
select is(private.current_agency_role('e9200000-0000-4000-8000-000000000001'),'admin','Correct admin role persisted');
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-7@example.test','QA','admin')$$,'42501',null,'New admin cannot invite another admin');
select is((select count(*) from public.agency_user_invitations where role='admin' and user_id is distinct from auth.uid()),0::bigint,'Admin cannot list other admin invitations');
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select lives_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000002','agency-user-5@example.test','QA','admin')$$,'Membership in A does not prevent invitation to B');
select set_config('test.other_agency_invitation',(select id::text from public.agency_user_invitations where agency_id='e9200000-0000-4000-8000-000000000002'),true);
reset role;
select public.finish_agency_user_invitation(current_setting('test.other_agency_invitation')::uuid,'e9100000-0000-4000-8000-000000000005',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.accept_agency_user_invitation(current_setting('test.other_agency_invitation')::uuid)$$,'Same identity accepts independent agency role');
select is(private.current_agency_role('e9200000-0000-4000-8000-000000000001'),'seller','Agency A role preserved');
select is(private.current_agency_role('e9200000-0000-4000-8000-000000000002'),'admin','Agency B role independent');
reset role;
update public.memberships set is_active=false where agency_id='e9200000-0000-4000-8000-000000000001' and user_id='e9100000-0000-4000-8000-000000000005';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e9100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.begin_agency_user_invitation('e9200000-0000-4000-8000-000000000001','agency-user-5@example.test','QA','seller')$$,'P0001',null,'Inactive membership cannot be reactivated by invitation');
select throws_ok($$insert into public.agency_user_invitations(agency_id,invited_by,email,display_name,role) values('e9200000-0000-4000-8000-000000000001',auth.uid(),'forged@example.test','QA','admin')$$,'42501',null,'No direct client insert');
select throws_ok($$delete from public.agency_user_invitations$$,'42501',null,'No direct client deletion');
reset role;
select is((select display_name from public.profiles where id='e9100000-0000-4000-8000-000000000005'),'QA usuarios','Existing profile preserved');
select * from finish();
rollback;
